sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
        try {
            //MSSCUSTODY-5608
            //Has added Amend-Error in when to run condition as part of MSSCUSTODY-6985
            var tradeAudExist = []; // to store single amend
            //MSSCUSTODY-5715
            var bulkAudExist = []; // to store bulk amend

            var amendObj = JSON.parse(current.request_body);

            var taskRecord = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
            taskRecord.addQuery('trade_case_id', current.sn_task.trade_case_id); // Filter by trade_case_id
            taskRecord.addQuery('trade_id', current.sn_task.trade_id);
            taskRecord.addQuery('trade_task_type', 'Maker');
            taskRecord.orderByDesc('sys_created_on'); // Arrange in descending order
            taskRecord.query();
            var tradeID;
            var taskID;
            var triggeredBy;
            var taskState;
            if (taskRecord.next()) {
                tradeID = taskRecord.trade_id.trade_id;
                taskID = taskRecord.number;
                //MSSCUSTODY-6826
                triggeredBy = taskRecord.trade_case_id.triggered_by.getDisplayValue();
				taskState = current.sn_task.state.getDisplayValue();

            }
            // Appending task ID 
            amendObj['PAYLOAD'].task_id = taskID.toString();
            amendObj['PAYLOAD'].trade_id = tradeID.toString();
            amendObj['PAYLOAD'].triggered_by = triggeredBy.toString();
            amendObj['PAYLOAD'].state = taskState.toString();

            //MSSCUSTODY-5715
            var finalPayload = amendObj['PAYLOAD'];
            var bulkRecord = new GlideRecord('x_hsb11_hsbc_mss_o_hsbc_bulk_transaction');
            bulkRecord.get(current.sn_task.bulk_id.sys_id);
            // Parse existing bulk_audit or initialize as an empty array
            if (bulkRecord.bulk_audit != '') {
                bulkAudExist = JSON.parse(bulkRecord.bulk_audit);
            } else {
                bulkAudExist = [];
            }

            // MSSCUSTODY-5608 : Fetching trade record
            var tradeRecord = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            tradeRecord.get(current.sn_task.trade_id.sys_id);
            //MSSCUSTODY-6826
            //Data from outbound will be parsed into GHSS array inside trad_audit field.
            //Modified as part of MSSCUSTODY-6826 for single amend.
            var tradeAudObj = {};
            if (!gs.nil(tradeRecord.trade_audit)) {
                try {
                    tradeAudObj = JSON.parse(tradeRecord.trade_audit);
                } catch (e) {
                    tradeAudObj = {};
                }
            }
            if (!Array.isArray(tradeAudObj.GHSS)) {
                tradeAudObj.GHSS = [];
            }

            // Append the payload to the GHSS array
            tradeAudObj.GHSS.push(finalPayload);


            // Append the payload to the appropriate audit field
            //MSSCUSTODY-5715
            bulkAudExist.push(finalPayload);
            bulkRecord.bulk_audit = JSON.stringify(bulkAudExist);

            // tradeAudExist.push(finalPayload);
            tradeRecord.trade_audit = JSON.stringify(tradeAudObj);

            // Update the trade record
            tradeRecord.update();
            //MSSCUSTODY-5715
            bulkRecord.update();

        }
    catch (ex) {
        gs.info('Business Rule - Populate Amend Audit History : Unknown exception occurred ' + ex.message);
    }
})(current, previous);
